// ── Customizing: the changes made from the panel, written to the `rooms` option ──
// Pure functions (tested): an edit gives a new `rooms` object, emptied lists and rooms are removed, and the dashboard
// configuration is patched where the card's options live — the strategy's when the dashboard is generated by
// `custom:wall-panel`, else the first `custom:wall-panel-card` found in its views.

const wpClone = (v) => JSON.parse(JSON.stringify(v ?? {}));
const wpList = (o, k) => (o[k] = Array.isArray(o[k]) ? o[k] : []);
const wpDrop = (list, id) => list.filter((x) => x !== id);

const wpTidy = (rooms) => {
  for (const [rid, o] of Object.entries(rooms)) {
    for (const k of ["hide", "pin", "include", "large", "order"]) if (Array.isArray(o[k]) && !o[k].length) delete o[k];
    if (o.group) {
      for (const [g, m] of Object.entries(o.group)) if (!m?.length) delete o.group[g];
      if (!Object.keys(o.group).length) delete o.group;
    }
    if (!Object.keys(o).length) delete rooms[rid];
  }
  return rooms;
};

// Every trace of `id` in `rooms` (Reset: back to what detection gives).
const wpForget = (rooms, id) => {
  for (const o of Object.values(rooms)) {
    for (const k of ["hide", "pin", "include", "large", "order"]) if (Array.isArray(o[k])) o[k] = wpDrop(o[k], id);
    if (o.hero === id) delete o.hero;
    if (o.group) {
      delete o.group[id];
      for (const g of Object.keys(o.group)) o.group[g] = wpDrop(o.group[g], id);
    }
  }
};

// edit: { size: normal|large|hero } | { move: area } | { pin: bool } | { show: bool } | { group: id } | { reset: true }
// `auto`: the entity is found by detection in `roomId` (so moving it away hides it there).
const wpApplyEdit = (rooms, roomId, id, edit, auto = true) => {
  const out = wpClone(rooms);
  const o = (out[roomId] ||= {});
  if (edit.reset) wpForget(out, id);
  else if (edit.size) {
    wpList(o, "large");
    o.large = wpDrop(o.large, id);
    if (o.hero === id) delete o.hero;
    if (edit.size === "large") o.large.push(id);
    if (edit.size === "hero") o.hero = id;
  } else if ("pin" in edit) {
    wpList(o, "pin");
    o.pin = wpDrop(o.pin, id);
    if (edit.pin) o.pin.push(id);
  } else if ("show" in edit) {
    wpList(o, "hide");
    o.hide = wpDrop(o.hide, id);
    if (!edit.show) o.hide.push(id);
  } else if (edit.move && edit.move !== roomId) {
    // Out of this room (hidden if detection put it here, dropped from include otherwise), into the other.
    wpList(o, "include");
    o.include = wpDrop(o.include, id);
    for (const k of ["pin", "large"]) if (Array.isArray(o[k])) o[k] = wpDrop(o[k], id);
    if (o.hero === id) delete o.hero;
    if (auto) {
      wpList(o, "hide");
      if (!o.hide.includes(id)) o.hide.push(id);
    }
    const dest = (out[edit.move] ||= {});
    wpList(dest, "hide");
    dest.hide = wpDrop(dest.hide, id);
    wpList(dest, "include");
    if (!dest.include.includes(id)) dest.include.push(id);
  } else if (edit.group) {
    o.group ||= {};
    const m = (o.group[id] ||= []);
    o.group[id] = m.includes(edit.group) ? wpDrop(m, edit.group) : [...m, edit.group];
  }
  return wpTidy(out);
};

// Finds where the card's options live in a dashboard configuration and returns a patched copy, or null.
const wpPatchLovelace = (lovelace, rooms) => {
  const out = wpClone(lovelace);
  if (out.strategy?.type === WP_STRATEGY) {
    out.strategy.rooms = rooms;
    return out;
  }
  let done = false;
  const walk = (node) => {
    if (done || !node || typeof node !== "object") return;
    if (!Array.isArray(node) && node.type === `custom:${WP_TAG}`) {
      node.rooms = rooms;
      done = true;
      return;
    }
    for (const v of Array.isArray(node) ? node : Object.values(node)) walk(v);
  };
  walk(out.views);
  return done ? out : null;
};

// `rooms:` as YAML, for a dashboard the panel cannot save itself.
const wpYaml = (rooms) => {
  const q = (s) => (/^[\w.-]+$/.test(s) ? s : JSON.stringify(s));
  const lines = ["rooms:"];
  for (const [rid, o] of Object.entries(rooms)) {
    lines.push(`  ${q(rid)}:`);
    for (const [k, v] of Object.entries(o)) {
      if (Array.isArray(v)) lines.push(`    ${k}: [${v.map(q).join(", ")}]`);
      else if (v && typeof v === "object") {
        lines.push(`    ${k}:`);
        for (const [g, m] of Object.entries(v)) lines.push(`      ${q(g)}: [${m.map(q).join(", ")}]`);
      } else lines.push(`    ${k}: ${typeof v === "string" ? q(v) : v}`);
    }
  }
  return lines.join("\n");
};

// The dashboard's url_path from the page address (/lovelace/0 → null, the default dashboard).
const wpDashboardPath = (pathname = globalThis.location?.pathname || "") => {
  const seg = pathname.split("/").filter(Boolean)[0];
  return !seg || seg === "lovelace" ? null : seg;
};
